function applySiteSettings(s){if(!s)return;if(s.whatsapp){const wd=String(s.whatsapp).replace(/\D/g,'');if(wd.length>=8&&wd.length<=15)BUSINESS.whatsapp=wd}if(s.email)BUSINESS.email=String(s.email);if(typeof s.offer_enabled!=='undefined')BUSINESS.offer.enabled=(String(s.offer_enabled).toLowerCase()==='true');if(s.offer_text)BUSINESS.offer.text=String(s.offer_text);BUSINESS.offer.badge=String(s.offer_badge||'');BUSINESS.offer.old=String(s.price_old||'');BUSINESS.offer.ends=String(s.offer_ends||'');BUSINESS.offer.style=String(s.offer_style||'gold');BUSINESS.prices.show=String(s.show_prices||'').toLowerCase()==='true';BUSINESS.prices.premium=String(s.price_premium||'');BUSINESS.prices.expert=String(s.price_expert||'');BUSINESS.prices.note=String(s.price_note||'');BUSINESS.payNote=String(s.pay_note||'');window.__payLoaded=false;window.__freeTrialMode=(typeof s.free_trial_mode!=='undefined')&&(String(s.free_trial_mode).toLowerCase()==='true')&&offerActive({enabled:true,ends:String(s.free_trial_ends||'')});try{renderOffer()}catch(e){}try{renderPrices()}catch(e){}try{const p=document.getElementById('paywall');if(p&&p.style.display==='flex')loadPayment()}catch(e){}try{const w=document.getElementById('waContact');if(w)w.textContent=BUSINESS.whatsapp;const m=document.getElementById('emailContact');if(m)m.textContent=BUSINESS.email}catch(e){}try{if(window.__freeTrialMode&&typeof fullRender==='function')fullRender()}catch(e){}}
function fetchSiteSettings(){try{const c=JSON.parse(localStorage.getItem('cvStudioSettingsCache')||'null');if(c&&c.s&&Date.now()-c.t<7*86400000){const run=()=>applySiteSettings(c.s);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run()}}catch(e){}if(typeof VERIFY_API_URL==='undefined'||VERIFY_API_URL.indexOf('PASTE_YOUR')===0)return;fetch(VERIFY_API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'getSettings'})}).then(r=>r.json()).then(d=>{if(d&&d.valid&&d.settings){try{localStorage.setItem('cvStudioSettingsCache',JSON.stringify({t:Date.now(),s:d.settings}))}catch(e){}applySiteSettings(d.settings)}}).catch(()=>{})}
