async function loadPayment(){const el=document.getElementById('payInfo');if(!el)return;if(window.__payData&&window.__payLoaded){el.innerHTML=payInfoHTML(window.__payData);return}el.innerHTML=payInfoHTML([]);const r=await verifyWithBackend({action:'getPayment'});if(r&&r.valid&&Array.isArray(r.slots)){window.__payData=r.slots.slice(0,3);window.__payLoaded=true;if(r.note)BUSINESS.payNote=String(r.note);const e2=document.getElementById('payInfo');if(e2)e2.innerHTML=payInfoHTML(window.__payData)}}
function customerUnlocked(){return localStorage.getItem('cvStudioUnlocked')==='1'||window.__freeTrialMode===true}
async function verifyWithBackend(payload){
  if(VERIFY_API_URL.indexOf('PASTE_YOUR')===0){return{valid:false,error:'setup_incomplete'}}
  try{
    const res=await fetch(VERIFY_API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)});
    return await res.json();
  }catch(err){
    return{valid:false,error:'network'};
  }
}
async function tryUnlockAccess(){
  const el=document.getElementById('unlockInput');
  const msg=document.getElementById('unlockMsg');
  const btn=document.getElementById('unlockBtn');
  const v=(el?el.value:'').trim();
  if(!v){if(msg)msg.textContent='Please enter your access code.';return}
  if(btn){btn.disabled=true;btn.textContent='Checking...'}
  const result=await verifyWithBackend({action:'verifyCustomer',code:v});
  if(btn){btn.disabled=false;btn.textContent='Unlock My CV'}
  if(result&&result.error==='setup_incomplete'){if(msg)msg.textContent='Setup incomplete: connect the Apps Script URL first.';return}
  if(result&&result.error==='network'){if(msg)msg.textContent='Could not reach the server. Please check your internet connection and try again.';return}
  if(result&&result.valid){
    localStorage.setItem('cvStudioUnlocked','1');
    if(msg)msg.textContent='Unlocked! You can now export your CV.';
    setTimeout(()=>{closeOrder();fullRender()},700)
  }else{
    if(msg)msg.textContent=(result&&result.reason==='too_many')?'Too many wrong attempts. Please wait 10 minutes and try again.':'Invalid or already-used code. Please check the code we sent you on WhatsApp.'
  }
}
