function esc(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function pct(v){v=Number(v);return isFinite(v)?Math.max(0,Math.min(100,Math.round(v))):0}
function safeColor(v,d){return /^#[0-9a-fA-F]{6}$/.test(String(v||''))?String(v):(d||'#000000')}
function cleanTheme(t,base){const o=Object.assign({},base);if(!t||typeof t!=='object')return o;['main','accent','bg','text','heading'].forEach(k=>{if(typeof t[k]==='string')o[k]=safeColor(t[k],base[k])});if(['sharp','rounded'].includes(t.corner))o.corner=t.corner;if(['compact','normal','airy'].includes(t.spacing))o.spacing=t.spacing;if(['clean','boxed','card'].includes(t.section)||typeof t.section==='string'&&/^[a-z]{1,12}$/.test(t.section))o.section=t.section;return o}
function sanitizeImport(d){const b=blank(),out={form:{},tech:null,theme:null,show:null,photoPlacement:null,photoFit:null,template:null};if(!d||typeof d!=='object'||Array.isArray(d))return out;Object.keys(b.form).forEach(k=>{if(k==='tech'||k==='expMore'||k==='eduMore')return;if(typeof d[k]==='string')out.form[k]=d[k].slice(0,20000)});['expMore','eduMore'].forEach(k=>{if(Array.isArray(d[k]))out.form[k]=d[k].slice(0,8).filter(x=>x&&typeof x==='object').map(x=>({t:String(x.t||'').slice(0,200),c:String(x.c||'').slice(0,200),d:String(x.d||'').slice(0,2000)}))});if(Array.isArray(d.tech))out.tech=d.tech.slice(0,30).filter(x=>x&&typeof x.name==='string').map(x=>({name:x.name.slice(0,80),level:pct(x.level)}));if(d.theme)out.theme=cleanTheme(d.theme,b.theme);if(d.show&&typeof d.show==='object'){out.show={};Object.keys(b.show).forEach(k=>{if(typeof d.show[k]==='boolean')out.show[k]=d.show[k]})}if(d.photoPlacement==='auto'||d.photoPlacement==='none')out.photoPlacement=d.photoPlacement;if(d.photoFit&&typeof d.photoFit==='object'){const n=(v,lo,hi,df)=>{v=Number(v);return isFinite(v)?Math.max(lo,Math.min(hi,v)):df};out.photoFit={zoom:n(d.photoFit.zoom,0.2,5,1),x:n(d.photoFit.x,0,100,50),y:n(d.photoFit.y,0,100,50)}}if(typeof d.template==='string')out.template=d.template;return out}
function splitList(v){return String(v||'').split(/[|,\n]/).map(x=>x.trim()).filter(Boolean)}
function tpl(){return templates.find(t=>t.id===state.template)||templates[0]}
function isPremium(){return tpl().premium||state.customTheme||!!state.frameTouched}
function firstNum(x){const m=String(x||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/);return m?parseFloat(m[0]):NaN}
function offerActive(o){if(!o||!o.enabled)return false;if(o.ends&&/^\d{4}-\d{2}-\d{2}$/.test(o.ends)){const end=new Date(o.ends+'T23:59:59');if(!isNaN(end)&&Date.now()>end.getTime())return false}return true}
function offerPct(old,cur){const a=firstNum(old),b=firstNum(cur);return(a>0&&b>0&&a>b)?Math.round((a-b)/a*100):0}
function fmtEnds(d){const m=String(d||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return'';return(+m[3])+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+m[2]-1]+' '+m[1]}
function offerHTML(o,pr,withCta){const st=['gold','purple','green','red','blue'].includes(o.style)?o.style:'gold';const showP=pr&&pr.show&&pr.premium;const pct=showP&&o.old?offerPct(o.old,pr.premium):0;const ends=fmtEnds(o.ends);return `<div class="offer3d of-${st}" role="region" aria-label="Special offer">${o.badge?`<span class="of-badge">${esc(o.badge)}</span>`:''}<span class="of-text">${esc(o.text)}</span>${showP?`<span class="of-price">${o.old?`<s aria-label="Old price">${esc(o.old)}</s>`:''}<b>${esc(pr.premium)}</b>${pct?`<span class="of-off">${pct}% OFF</span>`:''}</span>`:''}${ends?`<span class="of-ends">Offer ends ${esc(ends)}</span>`:''}${withCta?`<span class="of-cta"><a href="builder.html">Get this offer</a></span>`:''}</div>`}
