function photoFrameHTML(){const unlocked=true;const f=state.photoFrame;const shapes=[   ['circle','Circle'],   ['rounded','Rounded'],   ['square','Square'],   ['soft','Soft Card'],   ['double','Double Ring'],   ['hex','Hexagon'],   ['diamond','Diamond'] ];const lockNote='<p class="muted small">Try any frame and see it live. A custom frame is a premium design, so downloading needs an access code.</p>';return `<div class="formsec photo-frame-box"><h3>Photo Frame</h3>${lockNote}<div class="row"><div><label>Frame Shape</label><div class="actions">${shapes.map(([v,l])=>`<button class="btn ${f.shape===v?'dark':'light'}" onclick="setPhotoFrame('shape','${v}')">${l}</button>`).join('')}</div></div></div><div class="row"><div><label><input type="checkbox" ${f.outline?'checked':''} onchange="setPhotoFrame('outline',this.checked)"> Show Outline</label></div><div>${f.outline?`<label>Outline Color</label><input type="color" value="${safeColor(f.outlineColor,'#2563eb')}" onchange="setPhotoFrame('outlineColor',this.value)">`:''}</div></div></div>`}
function setPhotoFrame(key,value){state.frameTouched=true;state.photoFrame[key]=value;saveAuto();fullRenderKeepPosition()}function handlePhoto(input){
  const file=input.files?.[0];
  if(!file)return;

  if(!file.type.startsWith('image/')){
    alert('Please choose an image file (JPG or PNG).');
    return;
  }

  const reader=new FileReader();

  reader.onload=()=>{
    const data=reader.result;

    state.photo=data;
    state.photoThumb=data;

    // IMPORTANT:
    // Do not rebuild the whole builder here.
    refreshPreview();
    saveAuto();

    const img=new Image();

    img.onload=()=>{
      try{
        const maxSize=700;
        let w=img.width;
        let h=img.height;

        if(w>h && w>maxSize){
          h=Math.round(h*(maxSize/w));
          w=maxSize;
        }else if(h>maxSize){
          w=Math.round(w*(maxSize/h));
          h=maxSize;
        }

        const canvas=document.createElement('canvas');
        canvas.width=w;
        canvas.height=h;

        const ctx=canvas.getContext('2d');

        if(ctx){
          ctx.drawImage(img,0,0,w,h);
          state.photo=canvas.toDataURL('image/jpeg',0.82);
        }

        let tw=img.width;
        let th=img.height;
        const tMax=260;

        if(tw>th && tw>tMax){
          th=Math.round(th*(tMax/tw));
          tw=tMax;
        }else if(th>tMax){
          tw=Math.round(tw*(tMax/th));
          th=tMax;
        }

        const tCanvas=document.createElement('canvas');
        tCanvas.width=tw;
        tCanvas.height=th;

        const tCtx=tCanvas.getContext('2d');

        if(tCtx){
          tCtx.drawImage(img,0,0,tw,th);
          state.photoThumb=tCanvas.toDataURL('image/jpeg',0.6);
        }

        saveAuto();
        refreshPreview();

      }catch(e){
        console.error('Photo processing failed:',e);
        saveAuto();
        refreshPreview();
      }
    };

    img.onerror=()=>{
      console.warn('Photo optimization failed. Original photo will be used.');
      saveAuto();
      refreshPreview();
    };

    img.src=data;
  };

  reader.onerror=()=>{
    alert('This photo could not be read. Please try another JPG or PNG file.');
  };

  reader.readAsDataURL(file);
}
const TEMPLATES_WITH_DEFAULT_FRAME=['t34','t35','t36','t37','t38','t39','t40','t41','t1','t2','t3','t4','t5','t6','t7','t8','t9','t10','t11','t12','t13','t14','t15','t16','t17','t18','t19','t20','t21','t22','t23','t24'];
function photoFor(pos,circle=false){
  if(state.photoPlacement==='none')return'';
  if(state.photoPlacement!=='auto'&&state.photoPlacement!==pos)return'';

  const canCustomize=customerUnlocked()||ownerMode||!!state.frameTouched;
  const hasOwnDefaultFrame=TEMPLATES_WITH_DEFAULT_FRAME.includes(state.template);
  let extraStyle='';
  let cls=circle?'circle':'';

  const x=Number(state.photoFit.x)||50;
  const y=Number(state.photoFit.y)||50;
  const zoom=Number(state.photoFit.zoom)||1;

  const tx=(x-50)*0.7;
  const ty=(y-50)*0.7;

  if(canCustomize||hasOwnDefaultFrame){
    const f=state.photoFrame;
    const outlineColor=safeColor(f.outlineColor,'#2563eb');
    const hasOutline=!!f.outline;
    let radius='16px',wh='',clip='',shadow='';
    let borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:3px solid rgba(255,255,255,.85);';

    if(f.shape==='circle'){
      radius='50%';wh='width:96px;height:96px;';
    }else if(f.shape==='square'){
      radius='0';wh='width:96px;height:96px;';
    }else if(f.shape==='rounded'){
      radius='16px';wh='width:96px;height:112px;';
    }else if(f.shape==='soft'){
      radius='22px';wh='width:96px;height:112px;';
      shadow='box-shadow:0 14px 30px rgba(15,23,42,.22);';
      borderStyle=hasOutline?`border:5px solid ${outlineColor};`:'border:6px solid #fff;';
    }else if(f.shape==='double'){
      radius='50%';wh='width:96px;height:96px;';
      borderStyle='border:3px solid #fff;';
      shadow=`box-shadow:0 0 0 3px #fff,0 0 0 7px ${hasOutline?outlineColor:'#2563eb'};`;
    }else if(f.shape==='hex'){
      radius='0';wh='width:104px;height:104px;';
      clip='clip-path:polygon(25% 5%,75% 5%,100% 50%,75% 95%,25% 95%,0% 50%);';
      borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:4px solid rgba(255,255,255,.9);';
    }else if(f.shape==='diamond'){
      radius='0';wh='width:104px;height:104px;';
      clip='clip-path:polygon(50% 0%,100% 50%,50% 100%,0% 50%);';
      borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:4px solid rgba(255,255,255,.9);';
    }

    const PS={t40:1.6,t37:1.25,t34:1.25,t35:1.2,t36:1.2,t38:1.2,t39:1.15,t41:1.2};const k=PS[state.template]||1.15;wh=wh.replace(/(\d+)px/g,(m,n)=>Math.round(n*k)+'px');
    cls='';
    extraStyle=`overflow:hidden;flex-shrink:0;border-radius:${radius};${wh}${clip}${shadow}${borderStyle}`;
  }

  const imgStyle=`width:100%;height:100%;object-fit:cover;object-position:50% 50%;transform:translate(${tx}%,${ty}%) scale(${zoom})${state.photoFit.flip?' scaleX(-1)':''};transform-origin:50% 50%;`;

  return `<div class="cv-photo ${cls}" style="${extraStyle}">${state.photo?`<img src="${state.photo}" alt="profile" style="${imgStyle}">`:'Profile Photo'}</div>`;
}
