function exportBlockHTML(premium){const unlocked=customerUnlocked()||ownerMode;if(premium&&!unlocked)return `<div class="formsec"><h3>Premium selected</h3><p class="muted">Export/print is locked. Send order on WhatsApp with full CV data. Already paid? Click Order and enter your access code.</p><button class="btn pink" onclick="openOrder()">Order / Payment Options</button></div>`;if(premium&&unlocked)return `<div class="formsec"><h3>Premium unlocked</h3><p class="muted">${ownerMode&&!customerUnlocked()?'Owner mode: no code needed. You can print/save PDF or download Word.':'Your access code was accepted. You can print/save PDF or download Word.'}</p><div class="actions"><button class="btn green" onclick="exportPDF()">Print / Save PDF</button><button class="btn dark" onclick="exportWord()" id="wordBtn">Download Word</button></div></div>`;return `<div class="formsec"><h3>Free export</h3><p class="muted">Free template selected. You can print/save PDF or download Word.</p><div class="actions"><button class="btn green" onclick="exportPDF()">Print / Save PDF</button><button class="btn dark" onclick="exportWord()" id="wordBtn">Download Word</button><button class="btn pink" onclick="openOrder()">Order Expert CV</button></div></div>`}
/* CV Health Check: simple rule-based checklist (not a score, not a promise about ATS results) */
function healthChecks(){const f=state.form,out=[],T=v=>String(v==null?'':v).trim(),add=(ok,t,tip)=>out.push({ok:!!ok,t,tip});
 const exps=[{t:f.exp1t,c:f.exp1c,d:f.exp1d},{t:f.exp2t,c:f.exp2c,d:f.exp2d}].concat(Array.isArray(f.expMore)?f.expMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 const edus=[{t:f.edu1t,c:f.edu1c,d:f.edu1d},{t:f.edu2t,c:f.edu2c,d:f.edu2d}].concat(Array.isArray(f.eduMore)?f.eduMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 add(T(f.name)&&T(f.phone)&&T(f.email),'Name, phone and email are filled in','Add your full name, a phone number and an email address so employers can contact you.');
 if(T(f.email))add(/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(T(f.email)),'Email address looks valid','Check the email address. It should look like name@example.com.');
 add(T(f.job),'Job title is added under your name','Add the job title you are applying for, for example "Accountant" or "IT Support Technician".');
 const sl=T(f.summary).length;add(sl>=150&&sl<=650,'Summary has a good length','Write a short summary of 3 to 4 lines (about 150 to 650 characters): your experience, main skills and goal.'+(sl>650?' Yours is long.':sl>0?' Yours is short.':''));
 add(exps.length>0,'Work experience is added','Add your most recent job first. If you are a fresher, add an internship, training or a project instead.');
 if(exps.length){add(exps.every(x=>T(x.d).split(/\n+|(?<=[.!?])\s+/).filter(Boolean).length>=2),'Each job has at least 2 points','Describe each job in 2 to 5 short points, one duty or achievement per line.');
  add(exps.some(x=>/\d/.test(T(x.d))),'Results include numbers','Add numbers where you can, such as customers served, percentage improved or team size.')}
 add(edus.length>0,'Education is added','Add your latest qualification with the institute name.');
 add((f.tech||[]).filter(x=>T(x&&x.name)).length>=5,'At least 5 skills are listed','List at least 5 skills that match the job you want.');
 add(T(f.lang),'Languages are added','Add the languages you speak, for example Urdu, English.');
 const all=[f.name,f.job,f.summary,f.projects,f.certs,f.refs,f.customBody].concat(exps.map(x=>[x.t,x.c,x.d].join(' ')),edus.map(x=>[x.t,x.c,x.d].join(' '))).join(' ');
 add(!/\[[^\]]*\]|lorem ipsum|\bxxx+\b|your name|company name/i.test(all),'No placeholder text left','Replace placeholder text such as [Institute], [Year] or "Company Name" with real details.');
 const pg=(document.querySelectorAll('#cvPreview .cvpage')||[]).length;if(pg>0)add(pg<=2,'CV length is 2 pages or less','Most employers prefer a CV of 1 to 2 pages. Shorten older jobs or remove less important points.');
 return out}
function healthHTML(){const c=healthChecks(),ok=c.filter(x=>x.ok).length,pct=Math.round(ok/c.length*100);
 return `<div class="formsec hc"><h3>CV Health Check</h3><p class="small"><b>${ok} of ${c.length}</b> checks passed</p><div class="hc-bar" role="img" aria-label="${ok} of ${c.length} checks passed"><span style="width:${pct}%"></span></div><ul class="hc-list">${c.map(x=>`<li class="${x.ok?'hc-ok':'hc-todo'}"><span class="hc-ico" aria-hidden="true">${x.ok?'✓':'!'}</span><div><b>${esc(x.t)}</b>${x.ok?'':`<div class="small muted">${esc(x.tip)}</div>`}</div></li>`).join('')}</ul><button class="btn light" onclick="fullRenderKeepPosition()">Check again</button><p class="muted small">This is a simple checklist based on common CV practice. It does not guarantee interviews or how any employer's software will read your CV.</p></div>`}
/* Free users can see their own CV in a premium design (export of premium designs still needs an access code) */
const PREVIEW_PREMIUM=['t42','t34','t46','t44'];
function previewPremium(id){const t=templates.find(x=>x.id===id);if(!t||!t.premium)return;if(!tpl().premium&&!state._back)state._back=state.template;setTemplate(id);fullRender()}
function backToFree(){const id=state._back;state._back=null;const t=templates.find(x=>x.id===id);setTemplate(t&&!t.premium?id:'t21');fullRender()}
function premiumPreviewHTML(){if(customerUnlocked()||ownerMode)return'';
 const back=state._back&&templates.find(x=>x.id===state._back&&!x.premium);
 if(tpl().premium)return back?`<div class="formsec"><h3>Previewing a premium design</h3><p class="muted small">This is your own CV in a premium design. Premium designs need an access code to download or print.</p><button class="btn light" onclick="backToFree()">Back to my free design</button></div>`:'';
 return `<div class="formsec pp"><h3>See your CV in a premium design</h3><p class="muted small">Preview your own details in a premium layout. Your free design is kept, and you can switch back at any time.</p><div class="pp-grid">${PREVIEW_PREMIUM.map(id=>{const t=templates.find(x=>x.id===id);return t?`<button type="button" class="pp-item" onclick="previewPremium('${t.id}')" aria-label="Preview my CV in ${esc(t.name)}"><img src="img/templates/${t.id}.jpg" width="520" height="690" loading="lazy" alt=""><span>${esc(t.name)}</span></button>`:''}).join('')}</div></div>`}
function stepHTML(){const f=state.form,premium=isPremium();if(state.step===1)return `<div class="guided"><b>Start here</b><p class="muted small">New user? Press demo first. You can change template again at the final step without losing data.</p></div><div class="formsec"><h3>Quick start</h3><div class="actions"><button class="btn dark" onclick="fillDemo()">Fill Full Demo CV</button><button class="btn light" onclick="clearAll()">Clear All Data</button><button class="btn" onclick="setStep(2)">Start From Scratch</button></div></div><div class="formsec"><h3>Choose Template</h3><div class="layout-list">${templates.map(t=>`<button class="layout-btn ${state.template===t.id?'active':''}" onclick="setTemplate('${t.id}')"><b>${t.name}</b><br><span>${t.premium?'Premium':'Free'} · ${t.cat}</span></button>`).join('')}</div></div><div class="formsec"><h3>Import old resume text</h3><textarea placeholder="Paste old resume text here" oninput="setField('form.pasteResume',this.value)">${esc(f.pasteResume)}</textarea><button class="btn light" onclick="importResume()">Import Basic Details</button></div><div class="actions"><button class="btn" onclick="setStep(2)">Next: Personal Details</button></div>`;if(state.step===2)return `<div class="formsec"><h3>Personal Details</h3><div class="row"><div><label>Name</label><input value="${esc(f.name)}" oninput="setField('form.name',this.value)"></div><div><label>Job Title</label><input value="${esc(f.job)}" oninput="setField('form.job',this.value)"></div></div><div class="row"><div><label>Phone</label><input value="${esc(f.phone)}" type="tel" oninput="setField('form.phone',this.value)"></div><div><label>Email</label><input value="${esc(f.email)}" type="email" oninput="setField('form.email',this.value)"></div></div><label>Address</label><input value="${esc(f.address)}" oninput="setField('form.address',this.value)"><label>Summary</label><textarea id="summaryField" oninput="setField('form.summary',this.value)">${esc(f.summary)}</textarea><div class="row"><div><label>Years of experience (optional)</label><input value="${esc(f.years)}" inputmode="numeric" maxlength="2" placeholder="e.g. 3 (leave empty or 0 if fresh)" oninput="this.value=this.value.replace(/\D/g,'');setField('form.years',this.value)"></div><div></div></div><button class="btn orange" onclick="aiSummary()">Suggest Summary</button><p class="muted small" id="sumCount">Based on your job title and skills. Always read it and edit it so it describes you truthfully.</p></div>${personalFormHTML()}<div class="formsec"><h3>Profile Photo</h3><div class="row"><div><label>Upload Photo</label><input type="file" accept="image/*" onchange="handlePhoto(this)"></div><div><label>Photo</label><select onchange="setField('photoPlacement',this.value)"><option value="auto" ${state.photoPlacement==='auto'?'selected':''}>Show photo</option><option value="none" ${state.photoPlacement==='none'?'selected':''}>No photo</option></select><p class="muted small">Each template has its own fixed photo style and position.</p></div></div><div class="photo-tools"><div><label>Zoom</label><input type="range" min="1" max="1.9" step=".05" value="${state.photoFit.zoom}" oninput="setPhotoFit('zoom',this.value)"></div><div><label>Move Left/Right</label><input type="range" min="0" max="100" value="${state.photoFit.x}" oninput="setPhotoFit('x',this.value)"></div><div><label>Move Up/Down</label><input type="range" min="0" max="100" value="${state.photoFit.y}" oninput="setPhotoFit('y',this.value)"></div></div><div class="row"><div><label><input type="checkbox" ${state.photoFit.flip?'checked':''} onchange="setPhotoFit('flip',this.checked?1:0)"> Flip photo (mirror left/right)</label></div></div>${photoFrameHTML()}</div><div class="actions"><button class="btn light" onclick="setStep(1)">Back</button><button class="btn" onclick="setStep(3)">Next: Sections</button></div>`;if(state.step===3)return `<div class="formsec"><h3>Experience</h3><label>Experience 1</label><input placeholder="Job title" value="${esc(f.exp1t)}" oninput="setField('form.exp1t',this.value)"><input placeholder="Company" value="${esc(f.exp1c)}" oninput="setField('form.exp1c',this.value)"><textarea placeholder="Description" oninput="setField('form.exp1d',this.value)">${esc(f.exp1d)}</textarea><label>Experience 2</label><input placeholder="Job title" value="${esc(f.exp2t)}" oninput="setField('form.exp2t',this.value)"><input placeholder="Company" value="${esc(f.exp2c)}" oninput="setField('form.exp2c',this.value)"><textarea placeholder="Description" oninput="setField('form.exp2d',this.value)">${esc(f.exp2d)}</textarea>${extraBlocksHTML('expMore','Experience',3,'Job title','Company','Description')}<button class="btn light" type="button" onclick="addExtra('expMore')">+ Add another experience</button></div><div class="formsec"><h3>Education</h3><input placeholder="Degree / Certificate" value="${esc(f.edu1t)}" oninput="setField('form.edu1t',this.value)"><input placeholder="Institute" value="${esc(f.edu1c)}" oninput="setField('form.edu1c',this.value)"><textarea placeholder="Details" oninput="setField('form.edu1d',this.value)">${esc(f.edu1d)}</textarea><input placeholder="Second Degree / Certificate" value="${esc(f.edu2t)}" oninput="setField('form.edu2t',this.value)"><input placeholder="Institute" value="${esc(f.edu2c)}" oninput="setField('form.edu2c',this.value)"><textarea placeholder="Details" oninput="setField('form.edu2d',this.value)">${esc(f.edu2d)}</textarea>${extraBlocksHTML('eduMore','Education',3,'Degree / Certificate','Institute','Details')}<button class="btn light" type="button" onclick="addExtra('eduMore')">+ Add another education</button></div><div class="formsec"><h3>Skills</h3><label><input type="checkbox" ${state.skillBars?'checked':''} onchange="state.skillBars=this.checked;saveAuto();refreshPreview()"> Show skill bars</label>${skillRows()}<button class="btn light" onclick="addSkill()">Add Skill</button><label>Soft Skills</label><textarea oninput="setField('form.soft',this.value)">${esc(f.soft)}</textarea><label>Languages</label><textarea oninput="setField('form.lang',this.value)">${esc(f.lang)}</textarea></div><div class="formsec"><h3>Extra Sections</h3><label>Projects</label><textarea oninput="setField('form.projects',this.value)">${esc(f.projects)}</textarea><label>Certifications</label><textarea oninput="setField('form.certs',this.value)">${esc(f.certs)}</textarea><label>References</label><textarea oninput="setField('form.refs',this.value)">${esc(f.refs)}</textarea><div class="row"><div><label>Custom Title</label><input value="${esc(f.customTitle)}" oninput="setField('form.customTitle',this.value)"></div><div><label>Custom Text</label><input value="${esc(f.customBody)}" oninput="setField('form.customBody',this.value)"></div></div></div><div class="formsec"><h3>Show / Hide Sections</h3><div class="switchgrid">${Object.entries({summary:'Summary',experience:'Experience',education:'Education',tech:'Technical Skills',soft:'Soft Skills',lang:'Languages',projects:'Projects',certs:'Certifications',refs:'References',custom:'Custom',personal:'Personal Information'}).map(([k,v])=>`<label class="switchline"><input type="checkbox" ${state.show[k]?'checked':''} onchange="state.show['${k}']=this.checked;saveAuto();refreshPreview()"> ${v}</label>`).join('')}</div></div><div class="actions"><button class="btn light" onclick="setStep(2)">Back</button><button class="btn" onclick="setStep(4)">Next: Design & Export</button></div>`;return `<div class="formsec"><h3>Change Template Anytime</h3><p class="muted small">Data safe rahega. Yahan se final template select kar sakte hain.</p><div class="layout-list">${templates.map(t=>`<button class="layout-btn ${state.template===t.id?'active':''}" onclick="setTemplate('${t.id}')"><b>${t.name}</b><br><span>${t.premium?'Premium':'Free'} · ${t.cat}</span></button>`).join('')}</div></div><div class="formsec"><h3>Custom Theme <span class="tag premium">Premium</span></h3><p class="muted small">Design freely and see the result live. Downloading a custom or premium design needs an access code.</p><div class="actions"><button class="btn light" onclick="applyThemePreset('blue')">Blue Pro</button><button class="btn light" onclick="applyThemePreset('green')">Emerald</button><button class="btn light" onclick="applyThemePreset('gold')">Executive Gold</button><button class="btn light" onclick="applyThemePreset('peach')">Soft Peach</button><button class="btn light" onclick="applyThemePreset('minimal')">Minimal</button></div>${true?`<details><summary class="btn light" style="margin-top:10px">Advanced Customization</summary><div class="row3"><div><label>Main Color</label><input type="color" value="${safeColor(state.theme.main,'#1e3a8a')}" onchange="state.customTheme=true;setField('theme.main',this.value)"></div><div><label>Accent Color</label><input type="color" value="${safeColor(state.theme.accent,'#2563eb')}" onchange="state.customTheme=true;setField('theme.accent',this.value)"></div><div><label>CV Background</label><input type="color" value="${safeColor(state.theme.bg,'#ffffff')}" onchange="state.customTheme=true;setField('theme.bg',this.value)"></div><div><label>Text Color</label><input type="color" value="${safeColor(state.theme.text,'#111827')}" onchange="state.customTheme=true;setField('theme.text',this.value)"></div><div><label>Heading Color</label><input type="color" value="${safeColor(state.theme.heading,'#0f172a')}" onchange="state.customTheme=true;setField('theme.heading',this.value)"></div><div><label>Section Style</label><select onchange="state.customTheme=true;setField('theme.section',this.value)"><option value="soft" ${state.theme.section==='soft'?'selected':''}>Soft Cards</option><option value="clean" ${state.theme.section==='clean'?'selected':''}>Clean Lines</option><option value="sharp" ${state.theme.section==='sharp'?'selected':''}>Sharp Executive</option></select></div><div><label>Spacing</label><select onchange="state.customTheme=true;setField('theme.spacing',this.value)"><option value="compact" ${state.theme.spacing==='compact'?'selected':''}>Compact</option><option value="normal" ${state.theme.spacing==='normal'?'selected':''}>Normal</option><option value="airy" ${state.theme.spacing==='airy'?'selected':''}>Airy</option></select></div><div><label>Corners</label><select onchange="state.customTheme=true;setField('theme.corner',this.value)"><option value="rounded" ${state.theme.corner==='rounded'?'selected':''}>Rounded</option><option value="sharp" ${state.theme.corner==='sharp'?'selected':''}>Sharp</option></select></div></div></details>`:'<p class="muted small">🔒 Advanced Customization (colors, spacing, corners) unlocks after you order and enter your access code.</p>'}</div>${healthHTML()}${premiumPreviewHTML()}${exportBlockHTML(premium)}<div class="formsec"><h3>Save Work</h3><button class="btn light" onclick="saveDraft()">Save Draft</button><button class="btn light" onclick="loadDraft()">Load Draft</button><button class="btn danger" onclick="clearAll()">Clear All Data</button></div><div class="formsec owner-tools"><h3>Owner Order Tools</h3><textarea placeholder="Paste structured WhatsApp order" oninput="setField('form.pasteOrder',this.value)">${esc(f.pasteOrder)}</textarea><button class="btn orange" onclick="importStructured()">Import Order Text</button><button class="btn light" onclick="downloadOrderFile()">Download Current Order File</button><label>Import order file</label><input type="file" accept="application/json" onchange="importOrderFile(this)"><textarea readonly>${esc(orderText())}</textarea></div><div class="actions"><button class="btn light" onclick="setStep(3)">Back</button></div>`}
function builderHTML(){document.body.classList.toggle('owner',ownerMode);return `<nav class="nav"><div class="brand">CV Studio <span>Pro</span></div><div class="links"><a href="index.html">Home</a><a href="templates.html">Templates</a><a href="pricing.html">Pricing</a><a href="contact.html">Contact</a></div></nav><div class="paywall" id="paywall"><div class="paybox"><h2>Premium export locked</h2><p class="muted">This template or custom theme is premium. Send your order on WhatsApp. Your full CV data will be included automatically.</p><div id="payInfo"></div><div id="orderDone"></div><div class="txnbox"><label for="txnInput">Transaction ID (optional - enter it after you pay)</label><input id="txnInput" maxlength="40" autocomplete="off" placeholder="e.g. 1234567890"><p class="muted small">Payment screenshot: after you submit the order you get an Order Number. Send the screenshot with that number on WhatsApp.</p></div><div class="status">Status: Received → In Progress → Delivered</div><div class="actions"><button class="btn pink" id="sendOrderBtn" onclick="whatsappOrder()">Send Order on WhatsApp</button><button class="btn dark" id="submitOrderBtn" onclick="submitOrderOnline()">Submit Order Online</button><button class="btn light" onclick="closeOrder()">Close</button></div><p class="muted small">"Submit Order Online" sends your details to us directly (no WhatsApp needed). We still confirm payment manually, then email your unlock code.</p><div class="unlockbox"><label>Already paid? Enter your access code</label><input id="unlockInput" placeholder="Enter access code"><button class="btn dark" id="unlockBtn" onclick="tryUnlockAccess()">Unlock My CV</button><p class="muted small" id="unlockMsg"></p></div></div></div><button class="jump-fab" id="jumpFab" type="button" onclick="jumpPreview()">View CV Preview \u2193</button><div class="builder"><div class="formpanel"><div class="steps">${[1,2,3,4].map(n=>`<button class="step ${state.step===n?'active':''}" onclick="setStep(${n})">${['Start','Details','Sections','Design & Export'][n-1]}</button>`).join('')}</div>${stepHTML()}</div><div class="previewpanel"><div class="preview-toolbar"><b>Live CV Preview</b><p class="muted small">CV full view. If data is long, next page appears below.</p><button class="btn light small" onclick="document.getElementById('cvPreview')?.scrollTo({top:0,behavior:'smooth'})">Top of CV</button></div><div id="cvPreview">${renderCV()}</div></div></div>`}
function mini(t){const c=t.accent;const sq=['t1','t2','t4','t6','t9','t10','t11','t15','t19'].includes(t.id)?' sq':'';let body='';const lines='<div class="mini-line"></div><div class="mini-line" style="width:88%"></div><div class="mini-line" style="width:65%"></div><div class="mini-sec"><div class="mini-line" style="width:40%"></div><div class="mini-line"></div><div class="mini-line" style="width:82%"></div><div class="mini-line" style="width:60%"></div></div><div class="mini-sec"><div class="mini-line" style="width:35%"></div><div class="mini-line" style="width:75%"></div></div><div class="mini-sec"><div class="mini-line" style="width:45%"></div><div class="mini-line" style="width:55%"></div></div>';const sideIds=['t1','t9','t11','t25','t28','t31'];const sideColors={t1:'#111827',t9:'#0f766e',t11:'#581c87',t25:'#1d4ed8',t28:'#475569',t31:'#1d4ed8'};const centerIds=['t7','t8','t12','t15','t20','t27','t30'];const rightIds=['t3','t4','t5','t13','t14','t19','t23','t24','t26','t29','t32'];if(sideIds.includes(t.id))body=`<div class="mini-side" style="background:${sideColors[t.id]}"><div class="mini-photo${sq}"></div><div class="mini-line light"></div><div class="mini-line light"></div></div><div class="mini-main">${lines}</div>`;else if(['t2','t10'].includes(t.id))body=`<div class="mini-banner" style="background:${t.id==='t10'?'#334155':'#16a34a'}"><div class="mini-photo${sq}"></div><div><div class="mini-line light" style="width:90px"></div><div class="mini-line light" style="width:60px"></div></div></div><div class="mini-grid">${lines}${lines}</div>`;else if(t.id==='t6')body=`<div class="mini-exec-head"><div><div class="mini-line light" style="width:90px"></div><div class="mini-line light" style="width:55px"></div></div><div class="mini-photo${sq}"></div></div><div class="mini-grid"><div class="mini-sec" style="background:#fef3c7"></div>${lines}</div>`;else if(t.id==='t16')body=`<div class="mini-cv mini-diagonal"><div style="position:relative;padding:18px 12px 0 80px"><div class="mini-photo${sq}"></div><div class="mini-line dark"></div></div><div class="mini-grid">${lines}${lines}</div></div>`;else if(t.id==='t17')body=`<div style="height:95px;background:radial-gradient(circle at 50% -10%,#0ea5e9 0 55%,#fff 56%);padding:16px;text-align:center"><div class="mini-photo${sq}" style="margin:auto"></div></div><div class="mini-grid">${lines}${lines}</div>`;else if(t.id==='t18')body=`<div style="height:85px;background:linear-gradient(135deg,#111827 0 58%,#facc15 58%);padding:16px;color:white"><div class="mini-photo${sq}"></div></div><div class="mini-grid">${lines}${lines}</div>`;else if(t.id==='t21')body=`<div style="padding:14px 14px 0;border-top:7px solid ${c}"><div class="mini-line" style="width:70%"></div><div class="mini-line" style="width:50%"></div></div><div style="padding:0 14px">${lines}</div>`;else if(centerIds.includes(t.id))body=`<div style="padding:14px;border-top:7px solid ${c};text-align:center"><div class="mini-photo${sq}" style="margin:0 auto"></div>${lines}</div>`;else if(rightIds.includes(t.id))body=`<div style="padding:14px;border-top:7px solid ${c}"><div class="mini-photo${sq}" style="margin-left:auto"></div>${lines}</div>`;else body=`<div style="padding:14px;border-top:7px solid ${c}"><div class="mini-photo${sq}"></div>${lines}</div>`;return `<div class="template-thumb"><div class="mini-cv">${body}</div></div>`}
function templateCard(t){const pr=!!t.premium;return `<div class="template-card tpl3d ${pr?'premium-card':'free-card'} ${t.id==='t6'?'featured-template':''}"><a class="tpl-thumb" href="builder.html?template=${t.id}" aria-label="Use ${esc(t.name)} template"><img src="img/templates/${t.id}.jpg" width="520" height="690" loading="lazy" decoding="async" alt="${esc(t.name)} CV template preview"><span class="tpl-chip ${pr?'p':'f'}">${pr?'Premium':'Free'}</span></a><h3>${esc(t.name)}</h3><div class="tpl-tags"><span class="tag">${esc(t.cat)}</span></div><div class="actions"><a class="btn" href="builder.html?template=${t.id}">Use Template</a><a class="btn dark" href="builder.html?fresh=1&template=${t.id}">Start Fresh</a></div></div>`}
function renderHomeTemplates(){const el=document.getElementById('homeTemplates');const featuredIds=['t1','t2','t19','t20','t16','t9'];const picked=featuredIds.map(id=>templates.find(t=>t.id===id)).filter(Boolean);if(el)el.innerHTML=picked.map(templateCard).join('')}
function renderTemplatePage(){let active='All';const tabs=document.getElementById('tabs'),grid=document.getElementById('templateGrid');function draw(){tabs.innerHTML=categories.map(c=>`<button class="tab ${active===c?'active':''}" onclick="window.__setCat('${c}')">${c}</button>`).join('');grid.innerHTML=templates.filter(t=>active==='All'||(active==='Free'&&!t.premium)||(active==='Premium'&&t.premium)||t.cat===active).map(templateCard).join('')}window.__setCat=c=>{active=c;draw()};draw()}
function installCVFixes(){if(document.getElementById('cvStudioFixes'))return;const st=document.createElement('style');st.id='cvStudioFixes';st.textContent=`@page{size:A4;margin:0}#cvPreview,.cvbook,.cvpage{box-sizing:border-box}.cvpage{overflow:visible!important}.cvpage>*{min-width:0;max-width:100%;box-sizing:border-box}.cvpage p,.cvpage h1,.cvpage h2,.cvpage h3,.cvpage .cv-title,.cvpage .cv-sub,.cvpage .small,.cvpage .muted{overflow-wrap:anywhere!important;word-break:normal!important;min-width:0;max-width:100%}.cvpage img{display:block;max-width:100%;height:auto}.cv-photo{position:relative;isolation:isolate}.cv-photo img{display:block!important;max-width:none!important}.cv-photo:has(img){font-size:0}.cvpage .cv-body>*,.cvpage .cv-body-mono>*,.cvpage .mono-grid-body>*,.cvpage .crimson-body>*,.cvpage .cv-split-body>*,.cvpage .exec-grid>*{min-width:0!important;max-width:100%!important}@media print{html,body{width:210mm!important;margin:0!important;padding:0!important}body{overflow:visible!important}.wrap,.builder,.previewpanel{width:210mm!important;max-width:210mm!important;overflow:visible!important}.cvbook{width:210mm!important;display:block!important;gap:0!important}.cvpage{width:210mm!important;height:auto!important;min-height:297mm!important;max-height:none!important;margin:0!important;padding:15mm!important;box-sizing:border-box!important;overflow:visible!important;box-shadow:none!important;break-after:auto!important;page-break-after:auto!important}.cvpage+.cvpage{break-before:page;page-break-before:always}.cv-footer{left:15mm!important;right:15mm!important}.cvpage .cv-photo{overflow:hidden!important}.cvpage p,.cvpage div,.cvpage span{max-width:100%!important;overflow-wrap:anywhere!important}}`;document.head.appendChild(st)}
function initBuilder(){builderActive=true;installCVFixes();loadAuto();const q=new URLSearchParams(location.search);const tid=q.get('template');const validT=tid&&templates.some(t=>t.id===tid)?tid:null;const fresh=q.get('fresh')==='1';if(fresh)clearAll();if(validT&&(fresh||validT!==state.template))setTemplate(validT);if(q.has('fresh')||q.has('template')){try{history.replaceState(null,'',location.pathname)}catch(e){}}if(!fresh&&!validT)fullRender();else if(!document.getElementById('cvPreview'))fullRender();persistNow()}
